INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q001:fr', 'q001', 'fr', 'Premier arbre', 'Ton fragment est silencieux, mais un arbre solitaire se dresse encore. Son bois est la première chose que le monde te rend. Casse 8 bûches.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q002:fr', 'q002', 'fr', 'Planches', 'Fabrique 4 planches.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q003:fr', 'q003', 'fr', 'Établi', 'Les survivants ont toujours construit avant de comprendre. Fabrique un établi.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q004:fr', 'q004', 'fr', 'Bâtons', 'Fabrique 4 bâtons.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q005:fr', 'q005', 'fr', 'Pioche en bois', 'Fabrique une pioche en bois.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q006:fr', 'q006', 'fr', 'Galets', 'La pierre d''Aethelgard est rare ici : le Dévoreur n''a laissé que de la poussière et des galets. Fais un clic droit sur le sol de ton île, la main vide, pour ramasser 9 Stone Pebbles.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q007:fr', 'q007', 'fr', 'Premier pavé', 'Fabrique un pavé à partir de 9 galets.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q008:fr', 'q008', 'fr', 'Pioche en pierre', 'Fabrique une pioche en pierre.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q009:fr', 'q009', 'fr', 'Épée en bois', 'Fabrique une épée en bois.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q010:fr', 'q010', 'fr', 'Planter une pousse', 'Plante une pousse d''arbre.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q011:fr', 'q011', 'fr', 'Première récolte', 'Casse 8 cultures arrivées à maturité.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q012:fr', 'q012', 'fr', 'Pain', 'Fabrique du pain.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q013:fr', 'q013', 'fr', 'La Fountain', 'Un vieux souvenir remue dans la roche : l''Appel. Tu te rappelles comment façonner une Fountain. Fabrique une Fountain avec 4 pavés et 4 bûches.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q014:fr', 'q014', 'fr', 'Poser la Fountain', 'Pose ta Fountain sur ton île. Elle fait apparaître un pavé au-dessus d''elle toutes les 2 secondes.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q015:fr', 'q015', 'fr', 'Pavés de la Fountain', 'Casse 64 pavés.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q016:fr', 'q016', 'fr', 'Pavés de la Fountain II', 'Casse 128 pavés de plus.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q017:fr', 'q017', 'fr', 'Lire le plan', 'Lis le plan du générateur avec /guide.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q018:fr', 'q018', 'fr', 'Spring Stone', 'Pose la Spring Stone du côté sud de l''anneau de ta Fountain.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q019:fr', 'q019', 'fr', 'Briques de pierre', 'Obtiens 16 briques de pierre : fabrique-les à partir de pierre, ou utilise une scie de tailleur de pierre.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q020:fr', 'q020', 'fr', 'L''anneau', 'Pose 7 briques de pierre autour de ta Fountain (la Spring Stone prend le côté sud).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q021:fr', 'q021', 'fr', 'Générateur de pierre', 'L''anneau se ferme et le fragment respire à nouveau. Termine l''anneau : ta Fountain devient un générateur de pierre (fais un clic droit dessus pour voir ce qui manque).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q022:fr', 'q022', 'fr', 'Miner le générateur', 'Casse-y 64 pavés.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q023:fr', 'q023', 'fr', 'Pépite de fer', 'Trouve ta première pépite de fer dans ton générateur.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q024:fr', 'q024', 'fr', 'Réserve de pépites', 'Trouve 9 pépites de fer dans ton générateur.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q025:fr', 'q025', 'fr', 'Lingot de fer', 'Fabrique un lingot de fer.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q026:fr', 'q026', 'fr', 'Premier seau', 'Fabrique un seau.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q027:fr', 'q027', 'fr', 'Eau sans fond', 'Remplis ton seau à la Spring Stone.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q028:fr', 'q028', 'fr', 'Cuivre', 'Trouve 16 cuivres bruts dans ton générateur.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q029:fr', 'q029', 'fr', 'Charbon', 'Trouve 16 charbons dans ton générateur.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q030:fr', 'q030', 'fr', 'Or', 'Trouve une pépite d''or dans ton générateur.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q031:fr', 'q031', 'fr', 'Âge du Bronze', 'La Bronzite, le premier métal que l''Appel a enseigné aux survivants. Ton voyage au-delà de l''îlot commence. Trouve ta première Bronzite dans ton générateur.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q032:fr', 'q032', 'fr', 'Miner 250', 'Casse 250 pavés.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q033:fr', 'q033', 'fr', 'Miner 500', 'Casse 500 pavés.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q034:fr', 'q034', 'fr', 'Fondeur', 'Fabrique un four.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q035:fr', 'q035', 'fr', 'Rangement', 'Fabrique deux coffres.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q036:fr', 'q036', 'fr', 'Pioche en fer', 'Fabrique une pioche en fer.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q037:fr', 'q037', 'fr', 'Visiter le marché', 'Ouvre le marché avec /market.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q038:fr', 'q038', 'fr', 'Premières ventes', 'Gagne 200 pièces.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q039:fr', 'q039', 'fr', 'Plan des dunes', 'Lis les plans des autres générateurs avec /guide.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q040:fr', 'q040', 'fr', 'Grès', 'Fabrique 16 blocs de grès.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q041:fr', 'q041', 'fr', 'Anneau des dunes', 'Pose 7 blocs de grès autour d''une deuxième Fountain (une Spring Stone du côté sud).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q042:fr', 'q042', 'fr', 'Générateur des dunes', 'Termine l''anneau de grès : un générateur Dune produit du sable, du gravier et du sable rouge.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q043:fr', 'q043', 'fr', 'Sable', 'Casse 64 blocs de sable.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q044:fr', 'q044', 'fr', 'Gravier', 'Casse 64 blocs de gravier.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q045:fr', 'q045', 'fr', 'Sable rouge', 'Casse 16 blocs de sable rouge.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q046:fr', 'q046', 'fr', 'Verre', 'Fais fondre 8 verres : mets du sable dans un four et récupère le verre.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q047:fr', 'q047', 'fr', 'Béton', 'Fabrique 8 poudres de béton.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q048:fr', 'q048', 'fr', 'Encore du verre', 'Fais fondre 16 verres de plus (le verre teinté compte aussi).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q049:fr', 'q049', 'fr', 'Anneau de givre', 'Pose 7 blocs de verre autour d''une troisième Fountain (une Spring Stone du côté sud).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q050:fr', 'q050', 'fr', 'Générateur de givre', 'Termine l''anneau de verre : un générateur Frost produit des blocs de neige, de la glace compacte et du Frostium.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q051:fr', 'q051', 'fr', 'Neige', 'Casse 32 blocs de neige.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q052:fr', 'q052', 'fr', 'Glace', 'Casse 16 blocs de glace compacte.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q053:fr', 'q053', 'fr', 'Frostium', 'Trouve ton premier Frostium dans les blocs de ton générateur Frost.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q054:fr', 'q054', 'fr', 'Butin de Frostium', 'Trouve 8 Frostium dans les blocs de ton générateur Frost.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q055:fr', 'q055', 'fr', 'Deuxième source', 'Pose 2 Spring Stones de plus.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q056:fr', 'q056', 'fr', 'Plus de Fountains', 'Pose 3 Fountains de plus.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q057:fr', 'q057', 'fr', 'La Forge', 'La Forge est le cœur de tout camp de survivants : elle transforme la mémoire brute en outils. Fabrique une Forge avec un haut fourneau, 4 lingots de fer et 4 charbons, puis pose-la.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q058:fr', 'q058', 'fr', 'Ouvrir la Forge', 'Ouvre le menu de la Forge avec /forge.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q059:fr', 'q059', 'fr', 'Première forge', 'Récupère un Bronze Core à la Forge (/forge).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q060:fr', 'q060', 'fr', 'Élever le générateur', 'Atteins le palier II du générateur : forge un Bronze Core et fais un clic droit dessus sur ton île.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q061:fr', 'q061', 'fr', 'Minage palier II', 'Casse 500 pavés de plus.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q062:fr', 'q062', 'fr', 'Trésor de Bronzite', 'Trouve 12 Bronzite dans ton générateur.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q063:fr', 'q063', 'fr', 'Diamant', 'Trouve un diamant dans ton générateur.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q064:fr', 'q064', 'fr', 'Ember Core', 'Récupère un Ember Core à la Forge (/forge).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q065:fr', 'q065', 'fr', 'Palier III', 'Atteins le palier III du générateur : forge un Ember Core et fais un clic droit dessus sur ton île.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q066:fr', 'q066', 'fr', 'Débris antiques', 'Trouve des débris antiques dans ton générateur.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q067:fr', 'q067', 'fr', 'Miner 2 000', 'Casse 2 000 pavés.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q068:fr', 'q068', 'fr', 'Void Lens', 'Récupère une Void Lens à la Forge (/forge).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q069:fr', 'q069', 'fr', 'La Void Lens', 'À travers la lentille, tu entrevois la brèche que le Dévoreur a déchirée dans le ciel : la Faille. Atteins le palier IV du générateur : fais un clic droit sur la Void Lens sur ton île. Elle ouvre aussi ton End (/island end).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q070:fr', 'q070', 'fr', 'Voidglass', 'Trouve un Voidglass dans ton générateur.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q071:fr', 'q071', 'fr', 'Starcore', 'Trouve un Starcore Shard dans ton générateur.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q072:fr', 'q072', 'fr', 'Miner 5 000', 'Casse 5 000 pavés.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('hub_gate:fr', 'hub_gate', 'fr', 'La porte de l''île', 'Le bronze sur le dos, tu sens le fragment se desserrer. Au-delà de la porte, il y a d''autres survivants. Rends-toi au Hub avec /hub (et utilise /island pour revenir).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('hub_guard:fr', 'hub_guard', 'fr', 'Le Garde', 'Clique sur le Garde sur la place du Hub et écoute.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('hub_archivist:fr', 'hub_archivist', 'fr', 'L''Archiviste', 'L''Archiviste a gardé une clé taillée dans un éclat qui se souvient encore du ciel. Clique sur l''Archiviste sur la place du Hub : elle détient la clé de la Faille.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('hub_merchant:fr', 'hub_merchant', 'fr', 'Le Marchand', 'Clique sur le Marchand sur la place du Hub pour apprendre comment fonctionne le marché.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('hub_market_lesson:fr', 'hub_market_lesson', 'fr', 'Leçon de marché', 'Gagne 300 pièces.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('rift_enter:fr', 'rift_enter', 'fr', 'Entrer dans la Faille', 'Porte ta Echo Key jusqu''à l''arche de la Faille, à l''ouest de la place du Hub, et clique sur le Gardien de la Faille.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('echo_defeat:fr', 'echo_defeat', 'fr', 'Vaincre l''Écho de la Faille', 'Le premier Écho du Dévoreur hurle dans le ciel. Mets-y fin, et les Huit Royaumes seront à ta portée. Fais un clic droit sur la Echo Key sur l''autel de la Faille, puis vaincs l''Écho de la Faille. Il lâche le Wing Core qui t''accorde tes Ailes et éclaire la route vers le Quai des Huit.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q073:fr', 'q073', 'fr', 'Plan du Nether', 'Lis le plan du Nether avec /guide.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q074:fr', 'q074', 'fr', 'Briquet', 'Fabrique un briquet.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q075:fr', 'q075', 'fr', 'Allumer un portail', 'Pose 10 blocs d''obsidienne.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q076:fr', 'q076', 'fr', 'Entrer dans le Nether', 'Entre dans ton Nether.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q077:fr', 'q077', 'fr', 'Netherrack', 'Casse 64 blocs de netherrack.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q078:fr', 'q078', 'fr', 'Briques du Nether', 'Fabrique 16 briques du Nether.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q079:fr', 'q079', 'fr', 'Bloc de magma', 'Fabrique un bloc de magma avec 4 netherrack et 1 charbon.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q080:fr', 'q080', 'fr', 'Anneau de braise', 'Pose 7 briques du Nether autour d''une Fountain (un bloc de magma du côté sud).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q081:fr', 'q081', 'fr', 'Générateur de braise', 'Termine l''anneau avec un bloc de magma du côté sud : un générateur Ember produit du netherrack et du sable des âmes.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q082:fr', 'q082', 'fr', 'Bloc de quartz', 'Fabrique un bloc de quartz avec 4 quartz du Nether (du générateur Ember ou du marché).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q083:fr', 'q083', 'fr', 'Sable des âmes', 'Casse 32 blocs de sable des âmes.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q084:fr', 'q084', 'fr', 'Ember Sunstone', 'Trouve une Sunstone dans les blocs de ton générateur Ember.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q085:fr', 'q085', 'fr', 'Verrues', 'Casse 16 verrues du Nether.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q086:fr', 'q086', 'fr', 'Cubes de magma', 'Vaincs 10 cubes de magma (le Ember Spawn du Colosse de Lave).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q087:fr', 'q087', 'fr', 'Chasseur de piglins', 'Vaincs 20 piglins zombifiés.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q088:fr', 'q088', 'fr', 'Terrassier du netherrack', 'Casse 256 blocs de netherrack.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q089:fr', 'q089', 'fr', 'Terrassier des âmes', 'Casse 128 blocs de sable des âmes.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q090:fr', 'q090', 'fr', 'Miner 1 000 netherrack', 'Casse 1 000 blocs de netherrack.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q091:fr', 'q091', 'fr', 'Entrer dans l''End', 'Entre dans ton End avec /island end (il faut la Void Lens).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q092:fr', 'q092', 'fr', 'Pierre de l''End', 'Casse 64 blocs de pierre de l''End.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q093:fr', 'q093', 'fr', 'Mites du Vide', 'Vaincs 15 endermites (les Void Mites de l''Écho de la Faille).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q094:fr', 'q094', 'fr', 'Briques de l''End', 'Fabrique 16 briques de pierre de l''End.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q095:fr', 'q095', 'fr', 'Void Sigil', 'Récupère un Void Sigil à la Forge (/forge).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q097:fr', 'q097', 'fr', 'L''Écho de la Faille, encore', 'Vaincs l''Écho de la Faille 3 fois.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q098:fr', 'q098', 'fr', 'Maître de l''Écho de la Faille', 'Vaincs l''Écho de la Faille 10 fois.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q099:fr', 'q099', 'fr', 'Houe', 'Fabrique une houe en bois.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q100:fr', 'q100', 'fr', 'Labourer', 'Plante 16 cultures ou graines.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q101:fr', 'q101', 'fr', 'Blé', 'Casse 32 blés.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q102:fr', 'q102', 'fr', 'Carottes', 'Casse 16 carottes.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q103:fr', 'q103', 'fr', 'Pommes de terre', 'Casse 16 pommes de terre.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q104:fr', 'q104', 'fr', 'Miches', 'Fabrique 8 pains.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q105:fr', 'q105', 'fr', 'Planter une forêt', 'Plante 8 pousses d''arbre.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q106:fr', 'q106', 'fr', 'Bois de chauffe', 'Casse 64 bûches.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q107:fr', 'q107', 'fr', 'Souffleur de feuilles', 'Casse 64 feuilles de chêne.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q108:fr', 'q108', 'fr', 'Botte de foin', 'Fabrique une botte de foin.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q109:fr', 'q109', 'fr', 'Canne à sucre', 'Casse 32 cannes à sucre.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q110:fr', 'q110', 'fr', 'Carotte dorée', 'Fabrique une carotte dorée avec des pépites d''or et une carotte.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q111:fr', 'q111', 'fr', 'Pastèques', 'Casse 16 pastèques.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q112:fr', 'q112', 'fr', 'Citrouilles', 'Casse 8 citrouilles.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q113:fr', 'q113', 'fr', 'Parcelle', 'Plante 64 cultures ou graines.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q114:fr', 'q114', 'fr', 'Récolte 256', 'Casse 256 cultures.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q115:fr', 'q115', 'fr', 'Composteur', 'Fabrique un composteur.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q116:fr', 'q116', 'fr', 'Pomme dorée', 'Fabrique une pomme dorée.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q117:fr', 'q117', 'fr', 'Récolte 1 000', 'Casse 1 000 cultures.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q118:fr', 'q118', 'fr', 'Pêcheur', 'Pêche 20 poissons.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q119:fr', 'q119', 'fr', 'Bronze Cleaver', 'Récupère à la Forge (/forge) : Bronze Cleaver.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q120:fr', 'q120', 'fr', 'Bronze Pick', 'Récupère à la Forge (/forge) : Bronze Pick.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q121:fr', 'q121', 'fr', 'Rimeblade', 'Récupère à la Forge (/forge) : Rimeblade.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q122:fr', 'q122', 'fr', 'Rime Pick', 'Récupère à la Forge (/forge) : Rime Pick.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q123:fr', 'q123', 'fr', 'Solar Panel', 'Récupère à la Forge (/forge) : Solar Panel.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q124:fr', 'q124', 'fr', 'Copper Cable', 'Récupère à la Forge (/forge) : 4× Copper Cable.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q125:fr', 'q125', 'fr', 'Coal Generator', 'Récupère à la Forge (/forge) : Coal Generator.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q126:fr', 'q126', 'fr', 'Battery', 'Récupère à la Forge (/forge) : Battery.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q127:fr', 'q127', 'fr', 'Miner I', 'Récupère à la Forge (/forge) : Miner I.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q128:fr', 'q128', 'fr', 'Miner II', 'Récupère à la Forge (/forge) : Miner II.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q129:fr', 'q129', 'fr', 'Ashes Bastion Key', 'Récupère à la Forge (/forge) : Ashes Bastion Key.');
