INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q251:fr', 'q251', 'fr', 'Carrier', 'Casse 10 000 blocs, de n''importe quel type.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q252:fr', 'q252', 'fr', 'Titan de la carrière', 'Casse 50 000 blocs, de n''importe quel type.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q253:fr', 'q253', 'fr', 'Chasseur de minerai', 'Casse 250 blocs de minerai.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q254:fr', 'q254', 'fr', 'Chasseur de terrain', 'Vaincs 200 monstres, de n''importe quel type.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q255:fr', 'q255', 'fr', 'Chasseur de terrain II', 'Vaincs 1 000 monstres, de n''importe quel type.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q256:fr', 'q256', 'fr', 'Bronzite 50', 'Trouve 50 Bronzite dans ton générateur.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q257:fr', 'q257', 'fr', 'Frostium 25', 'Trouve 25 Frostium dans les blocs de ton générateur Frost.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q258:fr', 'q258', 'fr', 'Sunstone 10', 'Trouve 10 Sunstone dans les blocs de ton générateur Ember.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q259:fr', 'q259', 'fr', 'Diamants 20', 'Trouve 20 diamants dans ton générateur.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q260:fr', 'q260', 'fr', 'Débris 5', 'Trouve 5 débris antiques dans ton générateur.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q261:fr', 'q261', 'fr', 'Voidglass 3', 'Trouve 3 Voidglass dans ton générateur.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q262:fr', 'q262', 'fr', 'Starcore 2', 'Trouve 2 Starcore Shards dans ton générateur.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q263:fr', 'q263', 'fr', 'Étage 7, encore', 'Termine l''étage 7 trois fois de plus.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q264:fr', 'q264', 'fr', 'Des générateurs partout', 'Termine 3 anneaux de générateur de plus, de n''importe quel type (chaque anneau compte une fois).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q265:fr', 'q265', 'fr', 'Mineur du jour', 'Casse 200 blocs.');
