INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q267:fr', 'q267', 'fr', 'Fermier du jour', 'Casse 100 cultures.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q268:fr', 'q268', 'fr', 'Chasseur du jour', 'Vaincs 40 monstres.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q269:fr', 'q269', 'fr', 'Artisan du jour', 'Fabrique 20 planches.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q270:fr', 'q270', 'fr', 'Gagneur du jour', 'Gagne 1 000 pièces.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q271:fr', 'q271', 'fr', 'Mineur de la semaine', 'Casse 2 000 blocs.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q272:fr', 'q272', 'fr', 'Chasseur de la semaine', 'Vaincs 3 boss.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q273:fr', 'q273', 'fr', 'Pillard de la semaine', 'Termine 3 étages de donjon.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q274:fr', 'q274', 'fr', 'Gagneur de la semaine', 'Gagne 5 000 pièces.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q275:fr', 'q275', 'fr', 'Terrassier de la semaine', 'Casse 3 000 blocs.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q276:fr', 'q276', 'fr', 'Heure de gloire', 'Casse 1 000 blocs.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q277:fr', 'q277', 'fr', 'Cent victimes', 'Vaincs 100 monstres.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q278:fr', 'q278', 'fr', 'Baron du bois', 'Casse 1 000 bûches.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q279:fr', 'q279', 'fr', 'Baron des champs', 'Casse 1 000 cultures.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q280:fr', 'q280', 'fr', 'Cent planches', 'Fabrique 100 planches.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q281:fr', 'q281', 'fr', 'Forge de fer', 'Obtiens 16 lingots de fer : fais-les fondre ou fabrique-les à partir de pépites.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q282:fr', 'q282', 'fr', 'Forge de diamant', 'Fabrique une pioche en diamant.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q283:fr', 'q283', 'fr', 'Journée de pêche', 'Pêche 50 poissons.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q284:fr', 'q284', 'fr', 'Semaine de pêche', 'Pêche 250 poissons.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q285:fr', 'q285', 'fr', 'Terrassier', 'Casse 5 000 blocs.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q286:fr', 'q286', 'fr', 'Vague de zombies', 'Vaincs 100 zombies.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q287:fr', 'q287', 'fr', 'Vague de squelettes', 'Vaincs 100 squelettes.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q288:fr', 'q288', 'fr', 'Vague d''araignées', 'Vaincs 60 araignées.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q289:fr', 'q289', 'fr', 'Vague de creepers', 'Vaincs 40 creepers.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q290:fr', 'q290', 'fr', 'Vague d''endermites', 'Vaincs 40 endermites.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q291:fr', 'q291', 'fr', 'Siège de zombies', 'Vaincs 200 zombies.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('grove_01:fr', 'grove_01', 'fr', 'Par la Porte Verte', 'Au-delà de la deuxième Porte, l''air est lourd de lumière. Le Bosquet se souvient comment pousser. Allume la Sky Gate du Bosquet des Murmures (vaincs le Lava Colossus) et franchis-la au Quai des Huit (/quai).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('grove_02:fr', 'grove_02', 'fr', 'Sol moussu', 'Casse 32 blocs de mousse.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('grove_03:fr', 'grove_03', 'fr', 'Première récolte du Bosquet', 'Casse 16 cultures arrivées à maturité.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('grove_04:fr', 'grove_04', 'fr', 'Respirer les spores', 'Récolte des cultures mûres dans le Bosquet jusqu''à gagner l''affinité Respiration (40 récoltes) : la brume de spores ne t''atteint plus.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('grove_05:fr', 'grove_05', 'fr', 'Planter les racines', 'Plante 32 pousses d''arbre.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('grove_06:fr', 'grove_06', 'fr', 'Cœur de bois', 'Casse 64 bûches de palétuvier, le bois vivant du Bosquet.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('grove_07:fr', 'grove_07', 'fr', 'Dompter le vert', 'Fabrique un composteur.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('grove_08:fr', 'grove_08', 'fr', 'Laisse-le pousser', 'Continue de récolter dans le Bosquet jusqu''à gagner l''affinité Croissance (200 récoltes) : la poudre d''os fait avancer une culture d''un stade de plus, partout.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('grove_09:fr', 'grove_09', 'fr', 'Réveiller la Mycelial Queen', 'Vaincs la Mycelial Queen, Gardienne du Bosquet.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('heights_01:fr', 'heights_01', 'fr', 'Par la Porte Gelée', 'Au-delà de la troisième Porte, rien ne bouge si tu ne le fais pas bouger. Les Hauteurs gardent le temps dans leur glace. Allume la Sky Gate des Hauteurs Gelées (vaincs la Mycelial Queen) et franchis-la au Quai des Huit (/quai).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('heights_02:fr', 'heights_02', 'fr', 'Tailler la glace', 'Casse 32 blocs de glace compacte.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('heights_03:fr', 'heights_03', 'fr', 'Taille bleue', 'Casse 16 blocs de glace bleue.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('heights_04:fr', 'heights_04', 'fr', 'Chaleur', 'Taille de la glace dans les Hauteurs jusqu''à gagner l''affinité Chaleur (40 blocs) : le froid ne te mord plus.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('heights_05:fr', 'heights_05', 'fr', 'Flèches de cristal', 'Casse 8 amas d''améthyste, les cristaux des Hauteurs.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('heights_06:fr', 'heights_06', 'fr', 'Chambre froide', 'Fabrique un haut fourneau.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('heights_07:fr', 'heights_07', 'fr', 'Chasse aux vagabonds', 'Vaincs 20 vagabonds.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('heights_08:fr', 'heights_08', 'fr', 'Stase', 'Continue de tailler la glace dans les Hauteurs jusqu''à gagner l''affinité Stase (200 blocs) : accroupis-toi dans les airs pour ralentir ta chute, partout dans les Hauteurs.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('heights_09:fr', 'heights_09', 'fr', 'Réveiller le Boreal Watcher', 'Vaincs le Boreal Watcher, Gardien des Hauteurs.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('marsh_01:fr', 'marsh_01', 'fr', 'Par la Porte Brune', 'La cinquième Porte sent la terre mouillée et les vieux repas. Rien ici n''est jamais vraiment perdu. Allume la Sky Gate des Marais Putrides (vaincs la Mycelial Queen) et franchis-la au Quai des Huit (/quai).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('marsh_02:fr', 'marsh_02', 'fr', 'Racines boueuses', 'Casse 32 racines de palétuvier boueuses, là où suinte la Rot Resin.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('marsh_03:fr', 'marsh_03', 'fr', 'Nourrir la cuve', 'Fais un clic droit sur une Rot Vat avec des objets périmés (chair putréfiée, yeux d''araignée, os...) pour les récupérer.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('marsh_04:fr', 'marsh_04', 'fr', 'Air filtré', 'Récupère des objets jusqu''à gagner l''affinité Filtré (40 points) : le miasme ne t''affaiblit plus.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('marsh_05:fr', 'marsh_05', 'fr', 'Tas de slime', 'Casse 16 blocs de slime de la Décharge et de la Mangrove Pleureuse.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('marsh_06:fr', 'marsh_06', 'fr', 'Récupérateur', 'Continue de récupérer jusqu''à gagner l''affinité Récupérateur (200 points) : une Vat demande moins d''objets pour chaque tirage de Rot Resin.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('marsh_07:fr', 'marsh_07', 'fr', 'Digérer le Digesteur', 'Vaincs la Mire Abomination, Gardienne des Marais.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('citadel_01:fr', 'citadel_01', 'fr', 'Par la Porte Dorée', 'Au-delà de la quatrième Porte, les heures ne s''accordent pas entre elles. La Citadelle les compte toutes. Allume la Sky Gate de la Citadelle des Sables d''Or (vaincs la Mycelial Queen) et franchis-la au Quai des Huit (/quai).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('citadel_02:fr', 'citadel_02', 'fr', 'Dunes de la Citadelle', 'Casse 64 blocs de grès.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('citadel_03:fr', 'citadel_03', 'fr', 'Le temps s''accélère', 'Sois dans la Citadelle quand la Time Tide monte : tu te déplaces plus vite, et les Chrono Modules tournent vite.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('citadel_04:fr', 'citadel_04', 'fr', 'Le temps s''arrête', 'Sois dans la Citadelle quand la Time Tide s''arrête : tu te déplaces plus lentement, et les Chrono Modules mettent de côté les cycles perdus.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('citadel_05:fr', 'citadel_05', 'fr', 'L''or des sables', 'Récupère 16 lingots d''or pour forger le Chrono Module et le Sandglass.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('citadel_06:fr', 'citadel_06', 'fr', 'Retourner le Sandglass', 'Récupère un Sandglass à la Forge (/forge).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('citadel_07:fr', 'citadel_07', 'fr', 'Un module qui se souvient', 'Récupère un Chrono Module à la Forge (/forge).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('citadel_08:fr', 'citadel_08', 'fr', 'Réveiller le Temporal Pharaoh', 'Vaincs le Temporal Pharaoh, Gardien de la Citadelle.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('chop_logs:fr', 'chop_logs', 'fr', 'Bûcheron', 'Coupe 32 bûches.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('mine_stone:fr', 'mine_stone', 'fr', 'Tailleur de pierre', 'Mine 64 blocs de pierre.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('mine_ores:fr', 'mine_ores', 'fr', 'Prospecteur', 'Mine 16 minerais.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('harvest_crops:fr', 'harvest_crops', 'fr', 'Main verte', 'Récolte 48 cultures arrivées à maturité.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('kill_zombies:fr', 'kill_zombies', 'fr', 'Chasseur de zombies', 'Vaincs 15 zombies.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('kill_skeletons:fr', 'kill_skeletons', 'fr', 'Collectionneur d''os', 'Vaincs 15 squelettes.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('kill_spiders:fr', 'kill_spiders', 'fr', 'Coupeur de toiles', 'Vaincs 12 araignées.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('kill_creepers:fr', 'kill_creepers', 'fr', 'Désamorçage discret', 'Vaincs 8 creepers.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('kill_any:fr', 'kill_any', 'fr', 'Dératisation', 'Vaincs 40 monstres.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('go_fishing:fr', 'go_fishing', 'fr', 'Prise du jour', 'Pêche 12 poissons.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('fish_lots:fr', 'fish_lots', 'fr', 'Pêcheur de haute mer', 'Pêche 25 poissons.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('earn_small:fr', 'earn_small', 'fr', 'Argent de poche', 'Gagne 2 000 pièces.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('earn_big:fr', 'earn_big', 'fr', 'Marchand', 'Gagne 20 000 pièces.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('craft_planks:fr', 'craft_planks', 'fr', 'Charpentier', 'Fabrique 64 planches.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('craft_torches:fr', 'craft_torches', 'fr', 'Que la lumière soit', 'Fabrique 32 torches.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('enchant_item:fr', 'enchant_item', 'fr', 'Enchanteur', 'Enchante 3 objets.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('place_saplings:fr', 'place_saplings', 'fr', 'Reboisement', 'Plante 20 pousses d''arbre.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('place_blocks:fr', 'place_blocks', 'fr', 'Bâtisseur', 'Pose 200 blocs.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('visit_islands:fr', 'visit_islands', 'fr', 'Compagnons de survie', 'Visite des îles 3 fois.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('visit_nether:fr', 'visit_nether', 'fr', 'Touriste des scories', 'Visite ton Nether.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('visit_end:fr', 'visit_end', 'fr', 'Au bout du monde', 'Visite ton End.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('bazaar_visit:fr', 'bazaar_visit', 'fr', 'Lèche-vitrine', 'Ouvre le Sky Exchange et regarde ce que les survivants échangent.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('boss_hunt:fr', 'boss_hunt', 'fr', 'Tenir la ligne', 'Participe à la défaite d''un boss.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('start:fr', 'start', 'fr', 'L''Éveil', 'Tu te réveilles sur un fragment à la dérive d''Aethelgard, arraché au monde par le Dévoreur de Monde. Apprends à survivre, ramasse des galets et construis ta Fountain.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('generator:fr', 'generator', 'fr', 'Le premier vrai générateur', 'Les champs de stase du Dévoreur retiennent encore ton fragment. La Spring Stone et un anneau de briques de pierre transforment ta Fountain en générateur. Un mauvais anneau ne te coûte jamais rien.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('variety:fr', 'variety', 'fr', 'Des générateurs variés', 'Des dunes pour le sable et le gravier, du givre pour la glace et le Frostium. D''autres survivants répondent à l''Appel : le marché ouvre.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('tiers:fr', 'tiers', 'fr', 'Élever les générateurs', 'La Forge, les noyaux, les paliers I à IV. Les souvenirs cristallisés d''Aethelgard répondent à ton marteau, et les progrès s''accélèrent.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('rift:fr', 'rift', 'fr', 'Le Hub et la Faille', 'Avec l''armure de Bronze sur le dos, l''Appel te montre la sortie de l''îlot : le Hub, ses habitants, et la Faille où attend le premier Écho.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('nether:fr', 'nether', 'fr', 'Le Nether et la Braise', 'Ton fragment a un jumeau rouge de scories. Derrière un portail t''attendent le générateur Ember, le quartz et le sable des âmes.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('end:fr', 'end', 'fr', 'L''End et le Vide', 'La Void Lens ouvre /island end. L''Écho de la Faille hante le Vide.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('farm:fr', 'farm', 'fr', 'Agriculture et nourriture', 'Un travail tranquille pour un fragment qui réapprend à faire pousser des choses. À jouer en parallèle des générateurs.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('forging:fr', 'forging', 'fr', 'Forge et équipement', 'Tout ce que fabrique la Forge, des outils de bronze aux clés du Bastion.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('machines:fr', 'machines', 'fr', 'Machines et énergie', 'Du charbon, des câbles sur de la redstone, des batteries, des panneaux solaires, puis des Miners qui cassent le générateur à ta place.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('market:fr', 'market', 'fr', 'Marché et économie', 'Vends, achète et mets aux enchères. Le marché ne vend ni n''achète jamais les objets les plus rares.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('dungeons:fr', 'dungeons', 'fr', 'Donjons', 'Des salles et des secrets sous le Hub. Les étages 6 et 7 renferment les Wing Cores.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('bosses:fr', 'bosses', 'fr', 'Les Boss', 'Les Gardiens font respecter les lois du Dévoreur, et l''Écho de la Faille est sa faim arrachée. Chacun a sa silhouette et son point faible lumineux.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('mastery:fr', 'mastery', 'fr', 'Maîtrise', 'De longs objectifs pour les survivants qui ont tout fait.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('challenges:fr', 'challenges', 'fr', 'Défis', 'De longues journées de travail simple : de plus gros chiffres, une seule fois chacun.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('grove:fr', 'grove', 'fr', 'Le Bosquet des Murmures', 'Royaume 2. Des racines larges comme des tours, des spores qui luisent, des îles vivantes. La Reine Mycélienne garde les codes vivants de l''ancien monde.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('heights:fr', 'heights', 'fr', 'Les Hauteurs Gelées', 'Royaume 3. Des cités figées dans la glace, un froid qui est l''absence de mouvement, un ciel presque à portée de main. Le Guetteur Boréal tient le monde immobile.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('marsh:fr', 'marsh', 'fr', 'Les Marais Putrides', 'Royaume 5. Tout ce que le Dévoreur a jeté finit ici, et le Marais le garde. L''Abomination des Fanges digère ce que le monde rejette.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('citadel:fr', 'citadel', 'fr', 'La Citadelle des Sables d''Or', 'Royaume 4. Des rivières de poussière d''or qui coulent vers le haut, un sablier grand comme une tour. Le Pharaon Temporel compte les heures que le Dévoreur a volées.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q001:de', 'q001', 'de', 'Erster Baum', 'Dein Fragment ist still, doch ein einsamer Baum steht noch. Sein Holz ist das Erste, was die Welt dir zurückgibt. Baue 8 Baumstämme ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q002:de', 'q002', 'de', 'Bretter', 'Stelle 4 Bretter her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q003:de', 'q003', 'de', 'Werkbank', 'Überlebende haben immer gebaut, bevor sie verstanden. Stelle eine Werkbank her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q004:de', 'q004', 'de', 'Stöcke', 'Stelle 4 Stöcke her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q005:de', 'q005', 'de', 'Holzspitzhacke', 'Stelle eine Holzspitzhacke her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q006:de', 'q006', 'de', 'Kiesel', 'Der Stein Aethelgards ist hier knapp: Der Fresser hat nur Staub und Kiesel zurückgelassen. Rechtsklicke mit leerer Hand auf den Boden deiner Insel, um 9 Stone Pebbles aufzuheben.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q007:de', 'q007', 'de', 'Erster Bruchstein', 'Stelle einen Bruchstein aus 9 Kieseln her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q008:de', 'q008', 'de', 'Steinspitzhacke', 'Stelle eine Steinspitzhacke her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q009:de', 'q009', 'de', 'Holzschwert', 'Stelle ein Holzschwert her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q010:de', 'q010', 'de', 'Setzling pflanzen', 'Pflanze einen Setzling.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q011:de', 'q011', 'de', 'Erste Ernte', 'Baue 8 ausgewachsene Feldfrüchte ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q012:de', 'q012', 'de', 'Brot', 'Stelle Brot her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q013:de', 'q013', 'de', 'Die Fountain', 'Eine alte Erinnerung regt sich im Fels: der Ruf. Du erinnerst dich, wie man eine Fountain formt. Stelle eine Fountain aus 4 Bruchsteinen und 4 Baumstämmen her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q014:de', 'q014', 'de', 'Die Fountain aufstellen', 'Stelle deine Fountain auf deiner Insel auf. Sie erzeugt alle 2 Sekunden einen Bruchstein über sich.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q015:de', 'q015', 'de', 'Bruchstein der Fountain', 'Baue 64 Bruchsteine ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q016:de', 'q016', 'de', 'Bruchstein der Fountain II', 'Baue 128 weitere Bruchsteine ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q017:de', 'q017', 'de', 'Den Plan lesen', 'Lies den Generatorplan mit /guide.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q018:de', 'q018', 'de', 'Spring Stone', 'Setze den Spring Stone an die Südseite des Rings deiner Fountain.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q019:de', 'q019', 'de', 'Steinziegel', 'Besorge 16 Steinziegel: Stelle sie aus Stein her oder nutze eine Steinsäge.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q020:de', 'q020', 'de', 'Der Ring', 'Setze 7 Steinziegel um deine Fountain (der Spring Stone nimmt die Südseite).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q021:de', 'q021', 'de', 'Steingenerator', 'Der Ring schließt sich, und das Fragment atmet wieder. Vervollständige den Ring: Deine Fountain wird zum Steingenerator (Rechtsklick darauf zeigt, was fehlt).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q022:de', 'q022', 'de', 'Den Generator abbauen', 'Baue 64 Bruchsteine daraus ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q023:de', 'q023', 'de', 'Eisennugget', 'Finde deinen ersten Eisennugget in deinem Generator.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q024:de', 'q024', 'de', 'Nugget-Vorrat', 'Finde 9 Eisennuggets in deinem Generator.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q025:de', 'q025', 'de', 'Eisenbarren', 'Stelle einen Eisenbarren her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q026:de', 'q026', 'de', 'Erster Eimer', 'Stelle einen Eimer her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q027:de', 'q027', 'de', 'Bodenloses Wasser', 'Fülle deinen Eimer am Spring Stone.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q028:de', 'q028', 'de', 'Kupfer', 'Finde 16 rohe Kupfer in deinem Generator.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q029:de', 'q029', 'de', 'Kohle', 'Finde 16 Kohle in deinem Generator.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q030:de', 'q030', 'de', 'Gold', 'Finde einen Goldnugget in deinem Generator.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q031:de', 'q031', 'de', 'Bronzezeit', 'Bronzit, das erste Metall, das der Ruf die Überlebenden lehrte. Deine Reise jenseits der Insel beginnt. Finde dein erstes Bronzit in deinem Generator.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q032:de', 'q032', 'de', '250 abbauen', 'Baue 250 Bruchsteine ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q033:de', 'q033', 'de', '500 abbauen', 'Baue 500 Bruchsteine ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q034:de', 'q034', 'de', 'Schmelzer', 'Stelle einen Ofen her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q035:de', 'q035', 'de', 'Lagerung', 'Stelle zwei Truhen her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q036:de', 'q036', 'de', 'Eisenspitzhacke', 'Stelle eine Eisenspitzhacke her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q037:de', 'q037', 'de', 'Den Markt besuchen', 'Öffne den Markt mit /market.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q038:de', 'q038', 'de', 'Erste Verkäufe', 'Verdiene 200 Münzen.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q039:de', 'q039', 'de', 'Dünenplan', 'Lies die Pläne der anderen Generatoren mit /guide.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q040:de', 'q040', 'de', 'Sandstein', 'Stelle 16 Sandstein her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q041:de', 'q041', 'de', 'Dünenring', 'Setze 7 Sandsteinblöcke um eine zweite Fountain (ein Spring Stone an der Südseite).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q042:de', 'q042', 'de', 'Dünengenerator', 'Vervollständige den Sandsteinring: Ein Dune-Generator erzeugt Sand, Kies und roten Sand.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q043:de', 'q043', 'de', 'Sand', 'Baue 64 Sand ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q044:de', 'q044', 'de', 'Kies', 'Baue 64 Kies ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q045:de', 'q045', 'de', 'Roter Sand', 'Baue 16 roten Sand ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q046:de', 'q046', 'de', 'Glas', 'Schmelze 8 Glas: Lege Sand in einen Ofen und nimm das Glas heraus.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q047:de', 'q047', 'de', 'Beton', 'Stelle 8 Betonpulver her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q048:de', 'q048', 'de', 'Mehr Glas', 'Schmelze 16 weitere Glas (gefärbtes Glas zählt auch).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q049:de', 'q049', 'de', 'Frostring', 'Setze 7 Glasblöcke um eine dritte Fountain (ein Spring Stone an der Südseite).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q050:de', 'q050', 'de', 'Frostgenerator', 'Vervollständige den Glasring: Ein Frost-Generator erzeugt Schneeblöcke, Packeis und Frostium.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q051:de', 'q051', 'de', 'Schnee', 'Baue 32 Schneeblöcke ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q052:de', 'q052', 'de', 'Eis', 'Baue 16 Packeis ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q053:de', 'q053', 'de', 'Frostium', 'Finde dein erstes Frostium in den Blöcken deines Frost-Generators.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q054:de', 'q054', 'de', 'Frostium-Ausbeute', 'Finde 8 Frostium in den Blöcken deines Frost-Generators.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q055:de', 'q055', 'de', 'Zweite Quelle', 'Setze 2 weitere Spring Stones.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q056:de', 'q056', 'de', 'Mehr Fountains', 'Setze 3 weitere Fountains.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q057:de', 'q057', 'de', 'Die Forge', 'Die Forge ist das Herz jedes Lagers von Überlebenden: Sie macht aus roher Erinnerung Werkzeuge. Stelle eine Forge mit einem Schmelzofen, 4 Eisenbarren und 4 Kohle her und stelle sie auf.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q058:de', 'q058', 'de', 'Die Forge öffnen', 'Öffne das Menü der Forge mit /forge.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q059:de', 'q059', 'de', 'Erstes Schmieden', 'Hole einen Bronze Core aus der Forge (/forge).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q060:de', 'q060', 'de', 'Den Generator aufwerten', 'Erreiche Generatorstufe II: Schmiede einen Bronze Core und rechtsklicke damit auf deiner Insel.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q061:de', 'q061', 'de', 'Abbau auf Stufe II', 'Baue 500 weitere Bruchsteine ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q062:de', 'q062', 'de', 'Bronzit-Schatz', 'Finde 12 Bronzit in deinem Generator.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q063:de', 'q063', 'de', 'Diamant', 'Finde einen Diamanten in deinem Generator.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q064:de', 'q064', 'de', 'Ember Core', 'Hole einen Ember Core aus der Forge (/forge).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q065:de', 'q065', 'de', 'Stufe III', 'Erreiche Generatorstufe III: Schmiede einen Ember Core und rechtsklicke damit auf deiner Insel.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q066:de', 'q066', 'de', 'Antike Trümmer', 'Finde antike Trümmer in deinem Generator.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q067:de', 'q067', 'de', '2.000 abbauen', 'Baue 2.000 Bruchsteine ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q068:de', 'q068', 'de', 'Void Lens', 'Hole eine Void Lens aus der Forge (/forge).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q069:de', 'q069', 'de', 'Die Void Lens', 'Durch die Linse erhaschst du einen Blick auf die Lücke, die der Fresser in den Himmel gerissen hat: den Riss. Erreiche Generatorstufe IV: Rechtsklicke die Void Lens auf deiner Insel. Sie öffnet auch dein Ende (/island end).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q070:de', 'q070', 'de', 'Voidglass', 'Finde ein Voidglass in deinem Generator.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q071:de', 'q071', 'de', 'Starcore', 'Finde einen Starcore Shard in deinem Generator.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q072:de', 'q072', 'de', '5.000 abbauen', 'Baue 5.000 Bruchsteine ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('hub_gate:de', 'hub_gate', 'de', 'Das Inseltor', 'Mit Bronze auf dem Rücken spürst du, wie sich das Fragment lockert. Hinter dem Tor gibt es andere Überlebende. Reise mit /hub zum Hub (und nutze /island, um zurückzukehren).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('hub_guard:de', 'hub_guard', 'de', 'Der Wächter', 'Klicke auf dem Hub-Platz den Wächter an und hör zu.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('hub_archivist:de', 'hub_archivist', 'de', 'Die Archivarin', 'Die Archivarin hat einen Schlüssel aufbewahrt, geschnitten aus einem Splitter, der sich noch an den Himmel erinnert. Klicke auf dem Hub-Platz die Archivarin an: Sie hütet den Schlüssel zum Riss.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('hub_merchant:de', 'hub_merchant', 'de', 'Der Händler', 'Klicke auf dem Hub-Platz den Händler an, um zu erfahren, wie der Markt funktioniert.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('hub_market_lesson:de', 'hub_market_lesson', 'de', 'Marktlektion', 'Verdiene 300 Münzen.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('rift_enter:de', 'rift_enter', 'de', 'In den Riss eintreten', 'Bring deinen Echo Key zum Rissbogen westlich des Hub-Platzes und klicke den Rissbewacher an.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('echo_defeat:de', 'echo_defeat', 'de', 'Das Echo des Risses besiegen', 'Das erste Echo des Fressers schreit am Himmel. Beende es, und die Acht Reiche werden erreichbar. Rechtsklicke den Echo Key auf dem Rissaltar und besiege dann das Echo des Risses. Es lässt den Wing Core fallen, der dir deine Flügel verleiht und den Weg zum Quai des Huit erleuchtet.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q073:de', 'q073', 'de', 'Netherplan', 'Lies den Netherplan mit /guide.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q074:de', 'q074', 'de', 'Feuerzeug', 'Stelle ein Feuerzeug her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q075:de', 'q075', 'de', 'Ein Portal entzünden', 'Setze 10 Obsidian.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q076:de', 'q076', 'de', 'In den Nether eintreten', 'Betritt deinen Nether.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q077:de', 'q077', 'de', 'Netherrack', 'Baue 64 Netherrack ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q078:de', 'q078', 'de', 'Netherziegel', 'Stelle 16 Netherziegel her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q079:de', 'q079', 'de', 'Magmablock', 'Stelle einen Magmablock aus 4 Netherrack und 1 Kohle her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q080:de', 'q080', 'de', 'Glutring', 'Setze 7 Netherziegel um eine Fountain (ein Magmablock an der Südseite).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q081:de', 'q081', 'de', 'Glutgenerator', 'Vervollständige den Ring mit einem Magmablock an der Südseite: Ein Ember-Generator erzeugt Netherrack und Seelensand.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q082:de', 'q082', 'de', 'Quarzblock', 'Stelle einen Quarzblock aus 4 Netherquarz her (vom Ember-Generator oder vom Markt).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q083:de', 'q083', 'de', 'Seelensand', 'Baue 32 Seelensand ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q084:de', 'q084', 'de', 'Ember Sunstone', 'Finde einen Sunstone in den Blöcken deines Ember-Generators.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q085:de', 'q085', 'de', 'Warzen', 'Baue 16 Netherwarzen ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q086:de', 'q086', 'de', 'Magmawürfel', 'Besiege 10 Magmawürfel (der Ember Spawn des Lavakolosses).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q087:de', 'q087', 'de', 'Piglin-Jäger', 'Besiege 20 Zombifizierte Piglins.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q088:de', 'q088', 'de', 'Netherrack-Gräber', 'Baue 256 Netherrack ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q089:de', 'q089', 'de', 'Seelen-Gräber', 'Baue 128 Seelensand ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q090:de', 'q090', 'de', '1.000 Netherrack abbauen', 'Baue 1.000 Netherrack ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q091:de', 'q091', 'de', 'Das Ende betreten', 'Betritt dein Ende mit /island end (benötigt die Void Lens).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q092:de', 'q092', 'de', 'Endstein', 'Baue 64 Endstein ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q093:de', 'q093', 'de', 'Leeremilben', 'Besiege 15 Endermiten (die Void Mites des Echos des Risses).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q094:de', 'q094', 'de', 'Endziegel', 'Stelle 16 Endsteinziegel her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q095:de', 'q095', 'de', 'Void Sigil', 'Hole ein Void Sigil aus der Forge (/forge).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q097:de', 'q097', 'de', 'Das Echo des Risses, nochmal', 'Besiege das Echo des Risses 3-mal.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q098:de', 'q098', 'de', 'Meister des Echos des Risses', 'Besiege das Echo des Risses 10-mal.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q099:de', 'q099', 'de', 'Hacke', 'Stelle eine Holzhacke her.');
