INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q106:de', 'q106', 'de', 'Bauholz', 'Baue 64 Baumstämme ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q107:de', 'q107', 'de', 'Laubbläser', 'Baue 64 Eichenlaub ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q108:de', 'q108', 'de', 'Heuballen', 'Stelle einen Heuballen her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q109:de', 'q109', 'de', 'Zuckerrohr', 'Baue 32 Zuckerrohr ab.');
