INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q111:de', 'q111', 'de', 'Melonen', 'Baue 16 Melonen ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q112:de', 'q112', 'de', 'Kürbisse', 'Baue 8 Kürbisse ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q113:de', 'q113', 'de', 'Ackerparzelle', 'Pflanze 64 Feldfrüchte oder Samen.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q114:de', 'q114', 'de', '256 ernten', 'Baue 256 Feldfrüchte ab.');
