INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q117:de', 'q117', 'de', '1.000 ernten', 'Baue 1.000 Feldfrüchte ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q118:de', 'q118', 'de', 'Angler', 'Fange 20 Fische.');
