INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q122:de', 'q122', 'de', 'Rime Pick', 'Hole in der Forge (/forge): Rime Pick.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q123:de', 'q123', 'de', 'Solar Panel', 'Hole in der Forge (/forge): Solar Panel.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q124:de', 'q124', 'de', 'Copper Cable', 'Hole in der Forge (/forge): 4× Copper Cable.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q125:de', 'q125', 'de', 'Coal Generator', 'Hole in der Forge (/forge): Coal Generator.');
