INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q257:de', 'q257', 'de', 'Frostium 25', 'Finde 25 Frostium in den Blöcken deines Frost-Generators.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q258:de', 'q258', 'de', 'Sunstone 10', 'Finde 10 Sunstone in den Blöcken deines Ember-Generators.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q259:de', 'q259', 'de', 'Diamanten 20', 'Finde 20 Diamanten in deinem Generator.');
