INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q276:de', 'q276', 'de', 'Stunde der Macht', 'Baue 1.000 Blöcke ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q277:de', 'q277', 'de', 'Hundert Besiegte', 'Besiege 100 Mobs.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q278:de', 'q278', 'de', 'Holzbaron', 'Baue 1.000 Baumstämme ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q279:de', 'q279', 'de', 'Ackerbaron', 'Baue 1.000 Feldfrüchte ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q280:de', 'q280', 'de', 'Hundert Bretter', 'Stelle 100 Bretter her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q281:de', 'q281', 'de', 'Eisenwerk', 'Besorge 16 Eisenbarren: Schmelze sie oder stelle sie aus Nuggets her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q282:de', 'q282', 'de', 'Diamantwerk', 'Stelle eine Diamantspitzhacke her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q283:de', 'q283', 'de', 'Angeltag', 'Fange 50 Fische.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q284:de', 'q284', 'de', 'Angelwoche', 'Fange 250 Fische.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q285:de', 'q285', 'de', 'Gräber', 'Baue 5.000 Blöcke ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q286:de', 'q286', 'de', 'Zombiewelle', 'Besiege 100 Zombies.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q287:de', 'q287', 'de', 'Skelettwelle', 'Besiege 100 Skelette.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q288:de', 'q288', 'de', 'Spinnenwelle', 'Besiege 60 Spinnen.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q289:de', 'q289', 'de', 'Creeperwelle', 'Besiege 40 Creeper.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q290:de', 'q290', 'de', 'Endermitenwelle', 'Besiege 40 Endermiten.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('q291:de', 'q291', 'de', 'Zombiebelagerung', 'Besiege 200 Zombies.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('grove_01:de', 'grove_01', 'de', 'Durch das Grüne Tor', 'Hinter dem zweiten Tor ist die Luft schwer vom Licht. Der Hain erinnert sich, wie man wächst. Entzünde das Sky Gate des Flüsterhains (besiege den Lava Colossus) und tritt am Quai des Huit (/quai) hindurch.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('grove_02:de', 'grove_02', 'de', 'Moosiger Grund', 'Baue 32 Moosblöcke ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('grove_03:de', 'grove_03', 'de', 'Erste Ernte im Hain', 'Baue 16 ausgewachsene Feldfrüchte ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('grove_04:de', 'grove_04', 'de', 'Die Sporen atmen', 'Ernte ausgewachsene Feldfrüchte im Hain, bis du die Affinität Atmung erhältst (40 Ernten): Der Sporendunst berührt dich nicht mehr.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('grove_05:de', 'grove_05', 'de', 'Die Wurzeln pflanzen', 'Pflanze 32 Setzlinge.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('grove_06:de', 'grove_06', 'de', 'Kernholz', 'Baue 64 Mangrovenstämme ab, das lebende Holz des Hains.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('grove_07:de', 'grove_07', 'de', 'Das Grün zähmen', 'Stelle einen Komposter her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('grove_08:de', 'grove_08', 'de', 'Lass es wachsen', 'Ernte weiter im Hain, bis du die Affinität Wachstum erhältst (200 Ernten): Knochenmehl lässt eine Pflanze überall eine Stufe weiter wachsen.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('grove_09:de', 'grove_09', 'de', 'Die Mycelial Queen wecken', 'Besiege die Mycelial Queen, Wächterin des Hains.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('heights_01:de', 'heights_01', 'de', 'Durch das Gefrorene Tor', 'Hinter dem dritten Tor bewegt sich nichts, wenn du es nicht bewegst. Die Höhen bewahren die Zeit in ihrem Eis. Entzünde das Sky Gate der Gefrorenen Höhen (besiege die Mycelial Queen) und tritt am Quai des Huit (/quai) hindurch.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('heights_02:de', 'heights_02', 'de', 'Eis schneiden', 'Baue 32 Packeis ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('heights_03:de', 'heights_03', 'de', 'Blauer Schnitt', 'Baue 16 Blaueis ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('heights_04:de', 'heights_04', 'de', 'Wärme', 'Schneide Eis in den Höhen, bis du die Affinität Wärme erhältst (40 Blöcke): Die Kälte beißt dich nicht mehr.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('heights_05:de', 'heights_05', 'de', 'Kristalltürme', 'Baue 8 Amethystcluster ab, die Kristalle der Höhen.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('heights_06:de', 'heights_06', 'de', 'Kühllager', 'Stelle einen Schmelzofen her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('heights_07:de', 'heights_07', 'de', 'Vagantenjagd', 'Besiege 20 Vaganten.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('heights_08:de', 'heights_08', 'de', 'Stase', 'Schneide weiter Eis in den Höhen, bis du die Affinität Stase erhältst (200 Blöcke): Schleiche in der Luft, um deinen Fall zu bremsen, überall in den Höhen.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('heights_09:de', 'heights_09', 'de', 'Den Boreal Watcher wecken', 'Besiege den Boreal Watcher, Wächter der Höhen.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('marsh_01:de', 'marsh_01', 'de', 'Durch das Braune Tor', 'Das fünfte Tor riecht nach nasser Erde und alten Mahlzeiten. Nichts ist hier je wirklich verschwunden. Entzünde das Sky Gate der Fauligen Sümpfe (besiege die Mycelial Queen) und tritt am Quai des Huit (/quai) hindurch.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('marsh_02:de', 'marsh_02', 'de', 'Schlammige Wurzeln', 'Baue 32 schlammige Mangrovenwurzeln ab, aus denen Rot Resin quillt.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('marsh_03:de', 'marsh_03', 'de', 'Den Bottich füttern', 'Rechtsklicke einen Rot Vat mit verdorbenen Gegenständen (Zombiefleisch, Spinnenaugen, Knochen...), um sie zu verwerten.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('marsh_04:de', 'marsh_04', 'de', 'Gefilterte Luft', 'Verwerte, bis du die Affinität Gefiltert erhältst (40 Punkte): Der Miasma schwächt dich nicht mehr.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('marsh_05:de', 'marsh_05', 'de', 'Schleimhaufen', 'Baue 16 Schleimblöcke aus der Deponie und der Weinenden Mangrove ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('marsh_06:de', 'marsh_06', 'de', 'Verwerter', 'Verwerte weiter, bis du die Affinität Verwerter erhältst (200 Punkte): Ein Vat braucht für jeden Rot-Resin-Wurf weniger Gegenstände.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('marsh_07:de', 'marsh_07', 'de', 'Den Verdauer verdauen', 'Besiege die Mire Abomination, Wächterin der Sümpfe.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('citadel_01:de', 'citadel_01', 'de', 'Durch das Goldene Tor', 'Hinter dem vierten Tor sind sich die Stunden nicht einig. Die Zitadelle zählt sie alle. Entzünde das Sky Gate der Zitadelle der Goldenen Sande (besiege die Mycelial Queen) und tritt am Quai des Huit (/quai) hindurch.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('citadel_02:de', 'citadel_02', 'de', 'Dünen der Zitadelle', 'Baue 64 Sandsteinblöcke ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('citadel_03:de', 'citadel_03', 'de', 'Die Zeit beschleunigt', 'Sei in der Zitadelle, wenn die Time Tide aufwallt: Du bewegst dich schneller, und Chrono Modules laufen schnell.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('citadel_04:de', 'citadel_04', 'de', 'Die Zeit stockt', 'Sei in der Zitadelle, wenn die Time Tide stockt: Du bewegst dich langsamer, und Chrono Modules speichern die verlorenen Zyklen.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('citadel_05:de', 'citadel_05', 'de', 'Gold der Sande', 'Sammle 16 Goldbarren, um das Chrono Module und das Sandglass zu schmieden.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('citadel_06:de', 'citadel_06', 'de', 'Das Sandglass wenden', 'Hole ein Sandglass aus der Forge (/forge).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('citadel_07:de', 'citadel_07', 'de', 'Ein Modul, das sich erinnert', 'Hole ein Chrono Module aus der Forge (/forge).');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('citadel_08:de', 'citadel_08', 'de', 'Den Temporal Pharaoh wecken', 'Besiege den Temporal Pharaoh, Wächter der Zitadelle.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('chop_logs:de', 'chop_logs', 'de', 'Holzfäller', 'Fälle 32 Baumstämme.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('mine_stone:de', 'mine_stone', 'de', 'Steinmetz', 'Baue 64 Steinblöcke ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('mine_ores:de', 'mine_ores', 'de', 'Prospektor', 'Baue 16 Erze ab.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('harvest_crops:de', 'harvest_crops', 'de', 'Grüner Daumen', 'Ernte 48 ausgewachsene Feldfrüchte.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('kill_zombies:de', 'kill_zombies', 'de', 'Zombiejäger', 'Besiege 15 Zombies.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('kill_skeletons:de', 'kill_skeletons', 'de', 'Knochensammler', 'Besiege 15 Skelette.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('kill_spiders:de', 'kill_spiders', 'de', 'Netzschneider', 'Besiege 12 Spinnen.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('kill_creepers:de', 'kill_creepers', 'de', 'Stille Entschärfung', 'Besiege 8 Creeper.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('kill_any:de', 'kill_any', 'de', 'Schädlingsbekämpfung', 'Besiege 40 Mobs.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('go_fishing:de', 'go_fishing', 'de', 'Fang des Tages', 'Fange 12 Fische.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('fish_lots:de', 'fish_lots', 'de', 'Hochseeangler', 'Fange 25 Fische.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('earn_small:de', 'earn_small', 'de', 'Taschengeld', 'Verdiene 2.000 Münzen.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('earn_big:de', 'earn_big', 'de', 'Händler', 'Verdiene 20.000 Münzen.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('craft_planks:de', 'craft_planks', 'de', 'Zimmermann', 'Stelle 64 Bretter her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('craft_torches:de', 'craft_torches', 'de', 'Es werde Licht', 'Stelle 32 Fackeln her.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('enchant_item:de', 'enchant_item', 'de', 'Verzauberer', 'Verzaubere 3 Gegenstände.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('place_saplings:de', 'place_saplings', 'de', 'Aufforstung', 'Pflanze 20 Setzlinge.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('place_blocks:de', 'place_blocks', 'de', 'Baumeister', 'Platziere 200 Blöcke.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('visit_islands:de', 'visit_islands', 'de', 'Mitüberlebende', 'Besuche Inseln 3-mal.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('visit_nether:de', 'visit_nether', 'de', 'Schlackentourist', 'Besuche deinen Nether.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('visit_end:de', 'visit_end', 'de', 'Am Rand der Welt', 'Besuche dein Ende.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('bazaar_visit:de', 'bazaar_visit', 'de', 'Schaufensterbummel', 'Öffne die Sky Exchange und sieh, was die Überlebenden handeln.');
INSERT INTO quest_text (id, quest_id, lang, name, description) VALUES ('boss_hunt:de', 'boss_hunt', 'de', 'Die Linie halten', 'Beteilige dich am Sieg über einen Boss.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('start:de', 'start', 'de', 'Das Erwachen', 'Du erwachst auf einem treibenden Fragment von Aethelgard, vom Weltenfresser aus der Welt gerissen. Lerne zu überleben, sammle Kiesel und baue deine Fountain.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('generator:de', 'generator', 'de', 'Der erste echte Generator', 'Die Stasefelder des Fressers halten dein Fragment noch fest. Der Spring Stone und ein Ring aus Steinziegeln machen aus deiner Fountain einen Generator. Ein falscher Ring kostet dich nie etwas.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('variety:de', 'variety', 'de', 'Verschiedene Generatoren', 'Dünen für Sand und Kies, Frost für Eis und Frostium. Andere Überlebende folgen dem Ruf: Der Markt öffnet.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('tiers:de', 'tiers', 'de', 'Die Generatoren aufwerten', 'Die Forge, die Kerne, Stufen I bis IV. Die kristallisierten Erinnerungen Aethelgards antworten auf deinen Hammer, und der Fortschritt beschleunigt sich.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('rift:de', 'rift', 'de', 'Der Hub und der Riss', 'Mit der Bronzerüstung auf dem Rücken zeigt dir der Ruf den Weg von der Insel: der Hub, seine Bewohner und der Riss, in dem das erste Echo wartet.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('nether:de', 'nether', 'de', 'Der Nether und die Glut', 'Dein Fragment hat einen schlackenroten Zwilling. Hinter einem Portal warten der Ember-Generator, Quarz und Seelensand.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('end:de', 'end', 'de', 'Das Ende und die Leere', 'Die Void Lens öffnet /island end. Das Echo des Risses spukt in der Leere.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('farm:de', 'farm', 'de', 'Landwirtschaft und Essen', 'Ruhige Arbeit für ein Fragment, das wieder lernt, Dinge wachsen zu lassen. Spiel sie neben den Generatoren.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('forging:de', 'forging', 'de', 'Schmiede und Ausrüstung', 'Alles, was die Forge herstellt, von den Bronzewerkzeugen bis zu den Bastionsschlüsseln.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('machines:de', 'machines', 'de', 'Maschinen und Energie', 'Kohle, Kabel auf Redstone, Batterien, Solarpaneele und dann Miner, die den Generator für dich abbauen.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('market:de', 'market', 'de', 'Markt und Wirtschaft', 'Verkaufe, kaufe und versteigere. Der Markt verkauft oder kauft die seltensten Dinge nie.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('dungeons:de', 'dungeons', 'de', 'Verliese', 'Räume und Geheimnisse unter dem Hub. Die Etagen 6 und 7 bergen die Wing Cores.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('bosses:de', 'bosses', 'de', 'Die Bosse', 'Die Wächter halten die Gesetze des Fressers aufrecht, und das Echo des Risses ist sein abgerissener Hunger. Jeder hat seine eigene Silhouette und seine leuchtende Schwachstelle.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('mastery:de', 'mastery', 'de', 'Meisterschaft', 'Lange Ziele für Überlebende, die schon alles geschafft haben.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('challenges:de', 'challenges', 'de', 'Herausforderungen', 'Lange Tage einfacher Arbeit: größere Zahlen, jede nur einmal.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('grove:de', 'grove', 'de', 'Der Flüsterhain', 'Reich 2. Wurzeln so breit wie Türme, leuchtende Sporen, lebendige Inseln. Die Myzel-Königin hütet die lebenden Codes der alten Welt.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('heights:de', 'heights', 'de', 'Die Gefrorenen Höhen', 'Reich 3. Städte, im Eis erstarrt, eine Kälte, die die Abwesenheit von Bewegung ist, ein Himmel fast in Reichweite. Der Boreale Wächter hält die Welt still.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('marsh:de', 'marsh', 'de', 'Die Fauligen Sümpfe', 'Reich 5. Alles, was der Fresser weggeworfen hat, landet hier, und der Sumpf bewahrt es. Die Morastabscheulichkeit verdaut, was die Welt verwirft.');
INSERT INTO quest_category_text (id, category_id, lang, name, description) VALUES ('citadel:de', 'citadel', 'de', 'Die Zitadelle der Goldenen Sande', 'Reich 4. Flüsse aus Goldstaub, die aufwärts fließen, eine Sanduhr so groß wie ein Turm. Der Zeitpharao zählt die Stunden, die der Fresser gestohlen hat.');
